$ErrorActionPreference = 'Stop'
$OutputPath = Join-Path (Get-Location) 'docs/inventory_guide.pdf'
$W=595; $H=842; $script:C=[System.Text.StringBuilder]::new(); $pages=[System.Collections.Generic.List[byte[]]]::new(); $ascii=[Text.Encoding]::ASCII
function rgb([string]$h){$s=$h.TrimStart('#');$r=[Convert]::ToInt32($s.Substring(0,2),16);$g=[Convert]::ToInt32($s.Substring(2,2),16);$b=[Convert]::ToInt32($s.Substring(4,2),16);return ,@(($r/255.0),($g/255.0),($b/255.0))}
function rect([double]$x,[double]$y,[double]$w,[double]$h,[string]$color){$c=rgb $color;[void]$script:C.AppendFormat([Globalization.CultureInfo]::InvariantCulture,"{0:0.###} {1:0.###} {2:0.###} rg {3:0.##} {4:0.##} {5:0.##} {6:0.##} re f`n",$c[0],$c[1],$c[2],$x,$H-$y-$h,$w,$h)}
function txt([double]$x,[double]$y,[string]$s,[double]$size=9,[string]$color='#24364B',[bool]$bold=$false){$c=rgb $color;$f=if($bold){'F2'}else{'F1'};$s=$s.Replace('\','\\').Replace('(','\(').Replace(')','\)');[void]$script:C.AppendFormat([Globalization.CultureInfo]::InvariantCulture,"BT /{0} {1:0.##} Tf {2:0.###} {3:0.###} {4:0.###} rg 1 0 0 1 {5:0.##} {6:0.##} Tm ({7}) Tj ET`n",$f,$size,$c[0],$c[1],$c[2],$x,$H-$y,$s)}
function wrap([string]$s,[int]$limit){$out=[Collections.Generic.List[string]]::new();$line='';foreach($word in ($s -split '\s+')){if(!$word){continue};if(!$line){$line=$word}elseif(($line.Length+$word.Length+1)-le $limit){$line+=" $word"}else{$out.Add($line);$line=$word}};if($line){$out.Add($line)};return ,$out.ToArray()}
function para([double]$x,[double]$y,[string]$s,[double]$width=510,[double]$size=9,[string]$color='#536985',[double]$lead=13,[bool]$bold=$false){$lim=[Math]::Max(12,[int]($width/($size*.52)));foreach($line in (wrap $s $lim)){txt $x $y $line $size $color $bold;$y+=$lead};return $y}
function startPage([int]$n,[string]$title,[string]$subtitle){$script:C.Clear()|Out-Null;rect 0 0 $W $H '#F7F9FC';rect 0 0 $W 9 '#1679E8';txt 40 35 'MRP PORTAL  /  INVENTORY GUIDE' 8 '#657A94' $true;txt 40 72 $title 22 '#17365D' $true;[void](para 40 94 $subtitle 510 8.5 '#657A94' 11);rect 40 109 515 1 '#D9E3EF';txt 40 820 'Inventory | field reference and operating guide' 7 '#657A94';txt 538 820 ("{0:00}" -f $n) 8 '#1679E8' $true}
function section([double]$y,[string]$title){txt 40 $y $title 10 '#1679E8' $true;return $y+12}
function item([double]$y,[string]$key,[string]$body,[double]$max=500){txt 42 $y $key 8 '#245789' $true;$next=para 190 $y $body $max 8 '#475D78' 11;$next+3}
function endPage{$pages.Add($ascii.GetBytes($script:C.ToString()))}

