$script:C.Clear()|Out-Null;rect 0 0 $W $H '#17365D';rect 0 0 $W 12 '#43B9AB';txt 48 58 'MRP PORTAL  /  VISUAL OPERATING GUIDE' 8 '#A6DDD4' $true;txt 48 180 'INVENTORY' 34 '#FFFFFF' $true
[void](para 49 215 'A field-by-field explanation of the Inventory page, its tenant CSV import, stock meanings, and how supply changes an MRP plan.' 465 12 '#E0EAF6' 18)
rect 48 290 499 125 '#24496F';txt 67 320 'WHAT IS CONNECTED TODAY?' 9 '#A6DDD4' $true;[void](para 67 345 'The inventory list and CSV import use tenant database data. Add Inventory, the history tabs, movement chart, and several detail fields are sample UI and do not persist or load transaction history.' 455 10 '#FFFFFF' 15)
txt 48 480 'THE FLOW' 8 '#A6DDD4' $true;$flow=@('Plant + material','Opening stock','Reservations + receipts','MRP netting','Planned orders');$x=48;foreach($v in $flow){rect $x 503 96 32 '#24496F';txt ($x+7) 523 $v 6.4 '#FFFFFF' $true;$x+=100};[void](para 48 575 'MRP explodes forecast through the bill of materials, adds expected receipts, consumes projected stock, and recommends replenishment when stock would fall below its minimum.' 480 9 '#DCE7F4' 14);txt 48 800 'Purpose  |  page fields  |  upload contract  |  MRP effect' 7.5 '#B7C9DC';$pages.Add($ascii.GetBytes($script:C.ToString()))

