startPage 2 'Page map and summary cards' 'Tenant-backed list and importer, alongside controls that are still demonstrative.';$y=section 132 'HEADER AND SUMMARY';$rows=@(
@('Tenant selector','Selects the tenant database context. Confirm this before upload.'),@('Search','Client-side search across material/plant code, name, and category.'),@('Filters','Notification only; no filter panel or server query is connected.'),@('Upload type + Upload CSV','Inventory & stock CSV import; accepts .csv up to 10 MB. Success reloads list.'),@('Add Inventory','Opens a sample form. Submit updates browser state only, not database.'),@('Total Items','Count of API rows. Active material/plant pairs can show zero even without inventory record.'),@('Total Inventory Value','Sum of current stock x material unit_cost; illustrative INR formatting.'),@('Low Stock Items','Count where server status evaluates available quantity below minimum.'),@('Out of Stock Items','Count where on-hand quantity is zero.'),@('vs last month / arrow','Decorative fixed comparison; no historical comparison is calculated.')
);foreach($r in $rows){$y=item $y $r[0] $r[1]};$y+=6;$y=section $y 'HOW THE API BUILDS THE LIST';[void](para 42 $y 'GET /api/inventory returns active material x active plant combinations in the selected tenant. Missing inventory records are left-joined and shown as zero stock. An optional plantCode filter exists in the API but is not exposed on this screen. A failed request is caught as an empty list, so confirm logs/network before assuming the tenant has no stock.' 500 8.2 '#475D78' 12);endPage

# Page 3
startPage 3 'Tabs and table columns' 'The current status calculation and the limits of each tab.';$y=section 132 'TABS';$rows=@(@('All Items','All returned rows; works.'),@('Low Stock','Rows with API Low Stock status; works.'),@('Out of Stock','Rows with zero on-hand; works.'),@('In Transit','API does not emit this status today; tab typically empty. Transit still impacts MRP.'),@('Reserved','API does not emit this status today; tab typically empty.'),@('Non-Moving','No connected movement history/status; tab typically empty.'));foreach($r in $rows){$y=item $y $r[0] $r[1]};$y+=3;$y=section $y 'TABLE COLUMNS';$rows=@(@('Material Code','material_code + plant_code; that pair identifies one stock row.'),@('Material Name / Category / Unit','From material master description, category, and uom.'),@('Current Stock','on_hand_qty; physical/opening supply. Missing row displays zero.'),@('Reserved','reserved_qty. Displayed; not deducted by current forward MRP.'),@('Available Stock','max(current stock - reserved, 0), calculated by UI.'),@('Min. Stock','constraint min_stock_qty, else inventory safety_stock_min, else material safety_stock_min, else zero.'),@('Max. Stock','constraint max_storage_capacity, else inventory max_capacity, else material max_capacity, else zero.'),@('Last Receipt Date','Actually mapped to in_transit_due_date (expected arrival), not historical receipt date.'),@('Inventory Value','on_hand_qty x material unit_cost; display uses rupee sign.'),@('Status','On hand 0 = Out; else available below minimum = Low; otherwise In Stock.'),@('Selection / Actions / Footer','Checkboxes, action notification and page numbers are visual; footer count is client-filtered.'));foreach($r in $rows){$y=item $y $r[0] $r[1]};endPage

# Page 4
startPage 4 'CSV upload: exact field reference' 'All headers are required. The transit due-date column must exist, but its row value may be blank.';$csv=@(
@('plant_code','Plant master key; must exist.'),@('material_code','Material master key; must exist.'),@('on_hand_qty','Required numeric >= 0; current physical stock.'),@('reserved_qty','Required numeric >= 0 and cannot exceed on_hand_qty. UI subtracts it for Available Stock; MRP currently does not.'),@('in_transit_qty','Required numeric >= 0; inbound quantity waiting for arrival.'),@('in_transit_due_date','Header required, value optional. If present use YYYY-MM-DD. Blank date makes MRP count transit in first bucket.'),@('scheduled_receipts_qty','Required numeric >= 0; undated balance counted in first bucket. CSV does not load separately dated future receipts.')
);$y=section 132 'REQUIRED HEADERS';[void](para 42 $y 'plant_code,material_code,on_hand_qty,reserved_qty,in_transit_qty,in_transit_due_date,scheduled_receipts_qty' 500 7.2 '#245789' 10 $true);$y+=33;$y=section $y 'FIELD MEANINGS + VALIDATION';foreach($r in $csv){$y=item $y $r[0] $r[1]};$y+=6;$y=section $y 'EXAMPLE ROWS';[void](para 42 $y 'P_VAL,PK-BAG-45,12000,500,2000,2026-12-15,300' 500 7.4 '#245789' 10 $true);$y+=15;[void](para 42 $y 'P_VAL,RM-CLINKER,800,0,0,,0' 500 7.4 '#245789' 10 $true);$y+=25;[void](para 42 $y 'Use UTF-8 comma-delimited CSV, exact unique headers, one row per plant/material, matching column counts, and no N/A placeholders. Excel regional date display does not change the required ISO date value.' 500 7.7 '#765321' 11);endPage

