$objects=[Collections.Generic.List[byte[]]]::new()
function obj([string]$s){$objects.Add($ascii.GetBytes($s))}
obj ("<< /Type /Catalog /Pages 2 0 R >>")
$kids=@(for($i=0;$i -lt $pages.Count;$i++){"$((5+2*$i)) 0 R"})
$kidText=$kids -join " "
obj ("<< /Type /Pages /Kids [$kidText] /Count $($pages.Count) >>")
obj ("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>")
obj ("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>")
for($i=0;$i -lt $pages.Count;$i++){$p=5+2*$i;$s=$pages[$i];obj "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents $($p+1) 0 R >>";$st=$ascii.GetString($s);obj "<< /Length $($s.Length) >>`nstream`n$st`nendstream"}
$ms=[IO.MemoryStream]::new();$head=$ascii.GetBytes("%PDF-1.4`n%MRPGuide`n");$ms.Write($head,0,$head.Length);$offs=[Collections.Generic.List[long]]::new();$offs.Add(0);for($i=0;$i -lt $objects.Count;$i++){$offs.Add($ms.Position);$b=$ascii.GetBytes("$($i+1) 0 obj`n");$ms.Write($b,0,$b.Length);$ms.Write($objects[$i],0,$objects[$i].Length);$b=$ascii.GetBytes("`nendobj`n");$ms.Write($b,0,$b.Length)};$xref=$ms.Position;$sb=[Text.StringBuilder]::new();[void]$sb.Append("xref`n0 $($objects.Count+1)`n0000000000 65535 f `n");for($i=1;$i -lt $offs.Count;$i++){[void]$sb.AppendFormat([Globalization.CultureInfo]::InvariantCulture,"{0:0000000000} 00000 n `n",$offs[$i])};[void]$sb.Append("trailer`n<< /Size $($objects.Count+1) /Root 1 0 R >>`nstartxref`n$xref`n%%EOF`n");$b=$ascii.GetBytes($sb.ToString());$ms.Write($b,0,$b.Length);[IO.File]::WriteAllBytes($OutputPath,$ms.ToArray());Write-Host "Wrote $OutputPath ($($pages.Count) pages)"



